from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class NRCellIdentifier(SchemaObject):
    nr_cell_id = SchemaField(name='nrCellId', not_null=True)
    sub_cell_id = SchemaField(name='subCellId', not_null=True)

    def __init__(self, nr_cell_id, sub_cell_id):
        self.nr_cell_id = nr_cell_id
        self.sub_cell_id = sub_cell_id

        super(NRCellIdentifier, self).__init__()


class ElementsPolarization(SchemaObject):
    polarization = SchemaField(name='polarization', not_null=True)
    elements = SchemaField(name='arrayElements', many=True, not_null=True)
    antenna = SchemaField(name='antenna', not_null=True)

    def __init__(self, polarization, elements, antenna):
        self.polarization = polarization
        self.elements = elements
        self.antenna = antenna

        super(ElementsPolarization, self).__init__()


class RUSpecificParameters(SchemaObject):
    nr_cell_id = SchemaField(name='nrCellId', not_null=True)
    target_rmod = SchemaField(name='targetRMOD', not_null=True)
    elements_polarization = SchemaField(name='arrayElementsPolarization', klass=ElementsPolarization, many=True, optional=True)
    capture_activity_timer = SchemaField(name='captureActivityTimer', optional=True)

    def __init__(self, nr_cell_id, target_rmod, elements_polarization, capture_activity_timer):
        self.nr_cell_id = nr_cell_id
        self.target_rmod = target_rmod
        self.elements_polarization = elements_polarization
        self.capture_activity_timer = capture_activity_timer

        super(RUSpecificParameters, self).__init__()


class Configuration(SchemaObject):
    dl_nr_subcell_list = SchemaField(name='dlNrSubcellList',klass=NRCellIdentifier, many=True, optional=True)
    ul_nr_subcell_list = SchemaField(name='ulNrSubcellList', klass=NRCellIdentifier, many=True, optional=True)
    ru_iq_data_parameters_list = SchemaField(name='ruIqDataParametersList', klass=RUSpecificParameters, many=True, optional=True)
    capture_frame_offset = SchemaField(name='captureFrameOffset', optional=True)
    capture_on_event = SchemaField(name='captureOnEvent')
    capture_on_event_from_l1_hi_and_l1_low = SchemaField(name='captureOnEventFromL1HiAndL1Low')
    buffer_cycle = SchemaField(name='bufferCycle', optional=True)
    reason = SchemaField(name='reason', optional=True)

    def __init__(self, dl_nr_subcell_list, ul_nr_subcell_list, ru_iq_data_parameters_list, capture_frame_offset, capture_on_event,
                 capture_on_event_from_l1_hi_and_l1_low, buffer_cycle, reason):
        self.dl_nr_subcell_list = dl_nr_subcell_list
        self.ul_nr_subcell_list = ul_nr_subcell_list
        self.ru_iq_data_parameters_list = ru_iq_data_parameters_list
        self.capture_frame_offset = capture_frame_offset
        self.capture_on_event = capture_on_event
        self.capture_on_event_from_l1_hi_and_l1_low = capture_on_event_from_l1_hi_and_l1_low
        self.buffer_cycle = buffer_cycle
        self.reason = reason

        super(Configuration, self).__init__()


class M2mLocalL1IqConfigurationResponse(SchemaObject):
    status = SchemaField(name="status", not_null=True)
    configuration = SchemaField(name='configuration', klass=Configuration, optional=True)

    def __init__(self, status, configuration):
        self.configuration = configuration
        self.status = status

        super(M2mLocalL1IqConfigurationResponse, self).__init__()
